import java.io.BufferedReader;import java.io.InputStreamReader;import java.util.StringTokenizer;import java.util.Arrays;public class Main {public static void main(String[] args) throws Exception {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));int n = Integer.parseInt(br.readLine().trim());int[] arr = new int[n];StringTokenizer st = new StringTokenizer(br.readLine());for (int i = 0; i < n; i++) {arr[i] = Integer.parseInt(st.nextToken());}int inc = getLIS(arr, n, true);int dec = getLIS(arr, n, false);System.out.println(n - Math.max(inc, dec));}private static int getLIS(int[] arr, int n, boolean increasing) {int[] tails = new int[n];int len = 0;for (int x : arr) {int val = increasing ? x : -x;int i = 0, j = len;while (i < j) {int m = (i + j) / 2;if (tails[m] <= val) i = m + 1;else j = m;}tails[i] = val;if (i == len) len++;}return len;}}